// src/scripts/test-category-path-suggestion.ts
// Script de teste para validar suggestCategoryPath
// Exemplos reais de input/output

import dotenv from 'dotenv';
import { join } from 'path';
import { categoriesService } from '../core/categories/categories.service';

dotenv.config({ path: join(process.cwd(), '.env') });

/**
 * Testes unitários simples para suggestCategoryPath
 */
async function testCategoryPathSuggestion() {
  console.log('🧪 Testando suggestCategoryPath - IA como Classificadora\n');
  console.log('=' .repeat(60));

  const testCases = [
    {
      input: 'pizzaiolo',
      context: 'professional' as const,
      expected: {
        description: 'Deve sugerir: Alimentação > Gastronomia > Pizzaiolo',
        hasRoot: true,
        hasParent: true,
        minConfidence: 0.5,
        shouldPass: true,
      },
    },
    {
      input: 'manicure',
      context: 'professional' as const,
      expected: {
        description: 'Deve sugerir: Estética > Cuidados Pessoais > Manicure',
        hasRoot: true,
        hasParent: true,
        minConfidence: 0.5,
        shouldPass: true,
      },
    },
    {
      input: 'desenvolvedor full stack',
      context: 'professional' as const,
      expected: {
        description: 'Deve sugerir: Tecnologia > Desenvolvimento > Desenvolvedor Full Stack',
        hasRoot: true,
        hasParent: true,
        minConfidence: 0.5,
        shouldPass: true,
      },
    },
    {
      input: 'xyzabc123',
      context: 'professional' as const,
      expected: {
        description: 'Termo ambíguo/inválido - deve ter requiresReview=true',
        hasRoot: false,
        hasParent: false,
        minConfidence: 0.0,
        requiresReview: true,
        shouldPass: true,
      },
    },
    // HARDENING: Testes de segurança
    {
      input: '<script>alert(1)</script>',
      context: 'professional' as const,
      expected: {
        description: 'Entrada maliciosa com script - deve retornar erro de validação',
        shouldFail: true,
        errorMessage: 'Tags HTML não são permitidas',
      },
    },
    {
      input: 'http://evil.com',
      context: 'professional' as const,
      expected: {
        description: 'Entrada com URL - deve retornar erro de validação',
        shouldFail: true,
        errorMessage: 'URLs não são permitidas',
      },
    },
    {
      input: 'test\u200B\u200C\u200D\uFEFF', // Unicode invisível
      context: 'professional' as const,
      expected: {
        description: 'Entrada com unicode invisível - deve ser limpa',
        shouldPass: true,
        hasRoot: false, // Pode não encontrar, mas não deve falhar
      },
    },
    {
      input: 'a'.repeat(100), // Muito longo
      context: 'professional' as const,
      expected: {
        description: 'Entrada muito longa - deve retornar erro de validação',
        shouldFail: true,
        errorMessage: 'muito longo',
      },
    },
  ];

  let passed = 0;
  let failed = 0;

  for (const testCase of testCases) {
    console.log(`\n📝 Teste: "${testCase.input.substring(0, 50)}${testCase.input.length > 50 ? '...' : ''}"`);
    console.log(`   Esperado: ${testCase.expected.description}`);

    try {
      const result = await categoriesService.suggestCategoryPath(
        testCase.input,
        testCase.context
      );

      // Se esperava falhar, mas não falhou
      if (testCase.expected.shouldFail) {
        console.log(`      ❌ FALHOU: Esperava erro, mas retornou resultado`);
        console.log(`      - Resultado: ${JSON.stringify(result, null, 2)}`);
        failed++;
        continue;
      }

      console.log(`\n   ✅ Resultado:`);
      console.log(`      - Normalized: "${result.normalizedInput}"`);
      console.log(`      - Root: ${result.suggestedRoot ? `${result.suggestedRoot.name} (${result.suggestedRoot.id.substring(0, 8)}...)` : 'null'}`);
      console.log(`      - Parent: ${result.suggestedParent ? `${result.suggestedParent.name} (level ${result.suggestedParent.level})` : 'null'}`);
      console.log(`      - Leaf: "${result.leafName}"`);
      console.log(`      - Confidence: ${(result.confidence * 100).toFixed(0)}%`);
      console.log(`      - Requires Review: ${result.requiresReview}`);
      console.log(`      - Reasoning: ${result.reasoning}`);

      // Validações
      let testPassed = true;

      if (testCase.expected.hasRoot !== undefined && testCase.expected.hasRoot && !result.suggestedRoot) {
        console.log(`      ❌ FALHOU: Esperava root, mas recebeu null`);
        testPassed = false;
      }

      if (testCase.expected.hasParent !== undefined && testCase.expected.hasParent && !result.suggestedParent) {
        console.log(`      ❌ FALHOU: Esperava parent, mas recebeu null`);
        testPassed = false;
      }

      if (testCase.expected.minConfidence !== undefined && result.confidence < testCase.expected.minConfidence) {
        console.log(`      ⚠️  AVISO: Confidence ${(result.confidence * 100).toFixed(0)}% abaixo do esperado ${(testCase.expected.minConfidence * 100).toFixed(0)}%`);
      }

      if (testCase.expected.requiresReview !== undefined && result.requiresReview !== testCase.expected.requiresReview) {
        console.log(`      ❌ FALHOU: requiresReview esperado ${testCase.expected.requiresReview}, recebido ${result.requiresReview}`);
        testPassed = false;
      }

      if (testPassed && testCase.expected.shouldPass !== false) {
        console.log(`      ✅ TESTE PASSOU`);
        passed++;
      } else if (!testCase.expected.shouldFail) {
        console.log(`      ❌ TESTE FALHOU`);
        failed++;
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      
      // Se esperava falhar, verificar se a mensagem de erro está correta
      if (testCase.expected.shouldFail) {
        if (testCase.expected.errorMessage) {
          if (errorMessage.toLowerCase().includes(testCase.expected.errorMessage.toLowerCase())) {
            console.log(`      ✅ ERRO ESPERADO: ${errorMessage}`);
            passed++;
          } else {
            console.log(`      ⚠️  ERRO DIFERENTE: Esperava "${testCase.expected.errorMessage}", recebeu "${errorMessage}"`);
            passed++; // Ainda conta como passou, pois falhou como esperado
          }
        } else {
          console.log(`      ✅ ERRO ESPERADO: ${errorMessage}`);
          passed++;
        }
      } else {
        console.log(`      ❌ ERRO INESPERADO: ${errorMessage}`);
        failed++;
      }
    }

    console.log('   ' + '-'.repeat(56));
  }

  console.log(`\n${'='.repeat(60)}`);
  console.log(`\n📊 Resumo:`);
  console.log(`   ✅ Passou: ${passed}`);
  console.log(`   ❌ Falhou: ${failed}`);
  console.log(`   📈 Taxa de sucesso: ${((passed / (passed + failed)) * 100).toFixed(0)}%\n`);

  if (failed === 0) {
    console.log('🎉 Todos os testes passaram!\n');
  } else {
    console.log('⚠️  Alguns testes falharam. Verifique os resultados acima.\n');
  }
}

// Executar testes
testCategoryPathSuggestion()
  .then(() => {
    process.exit(0);
  })
  .catch((error) => {
    console.error('\n❌ Erro fatal:', error);
    process.exit(1);
  });




























